import { Select } from '@/components/ui/form';
import { useUser } from '@/lib/auth';
import { ROLES } from '@/lib/authorization';

import {
  UpdateUserRoleInput,
  useUpdateUserRole,
} from '../api/update-user-role';

type UpdateUserRoleProps = {
  id: string;
  role: UpdateUserRoleInput['role'];
};

export const UpdateUserRole = ({ id, role }: UpdateUserRoleProps) => {
  const user = useUser();
  const updateUserRoleMutation = useUpdateUserRole();

  return (
    <Select
      key={role}
      className="mt-0 py-1 pl-2 pr-8 text-sm"
      defaultValue={role}
      options={[
        { label: ROLES.ADMIN, value: ROLES.ADMIN },
        { label: ROLES.USER, value: ROLES.USER },
      ]}
      registration={{
        disabled: user.data?.id === id || updateUserRoleMutation.isPending,
        onChange: async (e) => {
          updateUserRoleMutation.mutate({
            userId: id,
            data: { role: e.target.value as UpdateUserRoleInput['role'] },
          });
        },
      }}
    />
  );
};
E
